/**
 * @name Path traversal in file serving
 * @description Serving files based on user input without proper validation can allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from web requests
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["path", "query", "match_info", "rel_url"] and
      source = attr
    )
    or
    // Request parameters
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("Request").getReturn().getMember(["query", "match_info"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember("path").getMember(["join", "exists"]).getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from user input $@.", source.getNode(), "here"
